// ---- Brightlane demo booking store -----------------------------------------
// In ACTIVE (production) executions this persists between chats through
// $getWorkflowStaticData('global'). In editor test runs the store resets on
// every run - for the workshop that doubles as the "reset" button.
const SLOT_HOURS = ['09:00', '10:00', '11:00', '12:00', '13:00', '14:00', '15:00', '16:00'];
const SERVICES = ['Home Deep Cleaning', 'Standard Home Cleaning', 'Plumbing Visit', 'Electrical Visit', 'HVAC Maintenance', 'Appliance Repair Visit'];

function isoDate(offsetDays) {
  const d = new Date();
  d.setDate(d.getDate() + (offsetDays || 0));
  const m = String(d.getMonth() + 1).padStart(2, '0');
  const day = String(d.getDate()).padStart(2, '0');
  return d.getFullYear() + '-' + m + '-' + day;
}

function seedStore() {
  const now = new Date().toISOString().slice(0, 16).replace('T', ' ');
  return [
    { ref: 'APT-0001', customer: 'Maya Chen',     phone: '555-0143', service: 'Home Deep Cleaning',     date: isoDate(3), time: '10:00', status: 'Confirmed', created: now },
    { ref: 'APT-0002', customer: 'Dmitri Volkov', phone: '555-0177', service: 'Appliance Repair Visit', date: isoDate(2), time: '14:00', status: 'Confirmed', created: now },
    { ref: 'APT-0003', customer: 'Elena Petrova', phone: '555-0164', service: 'Plumbing Visit',         date: isoDate(2), time: '16:00', status: 'Confirmed', created: now },
  ];
}

function getStore() {
  let store = null;
  try { store = $getWorkflowStaticData('global'); } catch (err) { store = null; }
  if (!store || typeof store !== 'object') {
    store = (globalThis.__brightlaneStore = globalThis.__brightlaneStore || {});
  }
  if (!Array.isArray(store.bookings)) store.bookings = seedStore();
  return store;
}

function nextRef(store) {
  let highest = 0;
  for (const b of store.bookings) {
    const m = /^APT-(\d+)$/.exec(String(b.ref || ''));
    if (m) highest = Math.max(highest, parseInt(m[1], 10));
  }
  return 'APT-' + String(highest + 1).padStart(4, '0');
}

// The agent sends its arguments as a JSON object (often serialised to a
// string). Accept either shape so both agent styles keep working.
function parseArgs() {
  let raw = (typeof query !== 'undefined' && query !== null) ? query : ($json && $json.query);
  if (typeof raw === 'string') {
    raw = raw.trim();
    if (!raw) return {};
    try { raw = JSON.parse(raw); } catch (err) {
      throw new Error('Input must be a JSON object, for example: ' + JSON.stringify({ date: isoDate(2) }));
    }
  }
  if (!raw || typeof raw !== 'object' || Array.isArray(raw)) {
    throw new Error('Input must be a JSON object');
  }
  return raw;
}

function isSunday(dateIso) {
  return new Date(dateIso + 'T12:00:00').getDay() === 0; // getDay(): 0 = Sunday
}

// input: {"date": "YYYY-MM-DD"}
const args = parseArgs();
const date = String(args.date || '').trim();
if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
  throw new Error('check_availability needs {"date":"YYYY-MM-DD"}. Today is ' + isoDate() +
    ". Convert the wording the customer used into ISO format yourself first.");
}
if (isSunday(date)) {
  return date + ' is a Sunday - Brightlane is closed on Sundays. Free slots: none. Offer Monday to Saturday.';
}
const store = getStore();
const taken = {};
for (const b of store.bookings) {
  if (b.status === 'Confirmed' && b.date === date) taken[b.time] = true;
}
const free = SLOT_HOURS.filter(function (h) { return !taken[h]; });
const takenList = SLOT_HOURS.filter(function (h) { return taken[h]; });
let msg = free.length
  ? date + ' free slots: ' + free.join(', ') + ' (hourly starts 09:00-16:00, one technician per slot).'
  : date + ' is fully booked - every hourly slot 09:00-16:00 is taken.';
if (takenList.length) msg += ' Taken: ' + takenList.join(', ') + '.';
return msg;

